function wallStats(cfg) {
  let pieces = 0;
  let equiv = 0;
  for (let d = 0; d < cfg.layers; d++) {
    for (let r = 0; r < cfg.rows; r++) {
      const offset = ((r + d) & 1) === 1;
      if (offset) {
        pieces += cfg.columns + 1;
        equiv += cfg.columns;
      } else {
        pieces += cfg.columns;
        equiv += cfg.columns;
      }
    }
  }
  return { pieces, mass: equiv * cfg.mass, equiv };
}

function createWorld(cfg) {
  const settings = {
    speed: clamp(+cfg.speed, 5, 45),
    columns: clamp(cfg.columns | 0, 4, 24),
    rows: clamp(cfg.rows | 0, 3, 16),
    layers: clamp(cfg.layers | 0, 1, 5),
    mass: clamp(+cfg.mass, 0.5, 12),
  };
  const bricks = [];
  let id = 2;
  const z0 = -settings.columns * BRICK_L / 2;
  const W = settings.columns * BRICK_L;
  for (let d = 0; d < settings.layers; d++) {
    const x = WALL_FRONT + BRICK_D * (d + 0.5);
    for (let r = 0; r < settings.rows; r++) {
      const y = BRICK_H * (r + 0.5);
      const offset = ((r + d) & 1) === 1;
      if (!offset) {
        for (let c = 0; c < settings.columns; c++) {
          bricks.push(makeBrick({
            id: id++, x, y, z: z0 + (c + 0.5) * BRICK_L,
            hx: BRICK_D / 2, hy: BRICK_H / 2, hz: BRICK_L / 2,
            mass: settings.mass, half: false, row: r, layer: d,
          }));
        }
      } else {
        bricks.push(makeBrick({
          id: id++, x, y, z: z0 + BRICK_L / 4,
          hx: BRICK_D / 2, hy: BRICK_H / 2, hz: BRICK_L / 4,
