function kinematicLaunch(world) {
  const car = world.car;
  const speed = world.cfg.speed;
  const a = speed * speed / (2 * RUNWAY);
  const t = world.simTime;
  const s = 0.5 * a * t * t;
  car.y = car.restY;
  car.z = 0;
  car.a = 0;
  car.vy = 0;
  car.vz = 0;
  car.w = 0;
  if (s >= RUNWAY) {
    car.x = car.spawnX + RUNWAY;
    car.vx = speed;
    car.wheelA = RUNWAY / WHEEL_R;
    return true;
  }
  car.x = car.spawnX + s;
  car.vx = a * t;
  car.wheelA = s / WHEEL_R;
  if (car.vx > 6) {
    const mark = (s / 0.18) | 0;
    if (mark !== world.lastSmoke) {
      world.lastSmoke = mark;
      const c = 1, sng = 0;
      const rx = car.x + CAR_REAR * 0.72;
      spawnBurst(world, rx, 0.08, 0.7, -1, 0.15, 0, 22, 'dust');
      spawnBurst(world, rx, 0.08, -0.7, -1, 0.15, 0, 22, 'dust');
    }
  }
  return false;
}

function step(world, dt) {
  if (world.phase === 'idle' || world.phase === 'settled') return;
  world.frame++;
  world.simTime += dt;
  if (world.phase === 'launch') {
    const hit = kinematicLaunch(world);
    updateParticles(world, dt);
    if (!hit) {
      world.moving = 0;
      return;
    }
    world.phase = 'dynamic';
    world.impactSpeed = world.cfg.speed;
    world.car.wheelsLocked = true;
    world.didImpactWake = false;
  }
  const car = world.car;
  const bricks = world.bricks;
  if (car.sleepT == null || car.sleepT < 0.45) car.vy -= GRAVITY * dt;
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (b.awake) b.vy -= GRAVITY * dt;
  }
  gatherContacts(world);
  let impactJ = 0;
  solveVelocity(world);
  for (let i = 0; i < world.contacts.length; i++) {
    const c = world.contacts[i];
    if (c.A === car || c.B === car || (c.B && c.B.type === 'brick' && c.jn > 40)) {
      impactJ += c.jn;
    }
  }
  if ((car.sleepT || 0) < 0.45) {
    clampBody(car);
    car.x += car.vx * dt;
    car.y += car.vy * dt;
    car.z += car.vz * dt;
    car.a += car.w * dt;
    if (!car.wheelsLocked) car.wheelA += car.vx / WHEEL_R * dt;
  }
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (!b.awake) continue;
    clampBody(b);
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.z += b.vz * dt;
    b.a += b.w * dt;
    syncRot(b);
  }
  syncRot(car);
  solvePositions(world);
  for (let i = 0; i < bricks.length; i++) syncRot(bricks[i]);
  syncRot(car);
  if (car.y < car.restY - 0.05 && car.vy < 0 && Math.abs(car.a) < 0.2) {
    /* suspension floor is the wheel constraint */
  }
  updateSleep(world);
  if (impactJ > 30) {
    world.shake = Math.min(16, world.shake + impactJ * 0.0015);
    world.flash = Math.min(1, world.flash + impactJ * 0.00004);
    let nSpawn = 0;
    for (let i = 0; i < world.contacts.length && nSpawn < 10; i++) {
      const c = world.contacts[i];
      if (c.jn < 25) continue;
      if ((c.A && c.A.type === 'brick') || (c.B && c.B.type === 'brick')) {
        spawnBurst(world, c.px, Math.max(0.1, c.py), c.pz || 0, c.nx, c.ny, c.nz, c.jn, nSpawn % 3 === 0 ? 'spark' : 'dust');
        nSpawn++;
      }
    }
  }
  world.shake *= Math.exp(-dt * 5.5);
  world.flash *= Math.exp(-dt * 7);
  updateParticles(world, dt);
  updateSkids(world);
  world.moving = countMoving(world);
  const cs = hypot3(car.vx, car.vy, car.vz);
  if (world.simTime > 0.35 && cs < 0.18 && world.moving === 0) {
    world.stillT += dt;
    if (world.stillT > 0.55) world.phase = 'settled';
  } else world.stillT = 0;
  let maxPen = 0;
  let awake = 0;
  for (let i = 0; i < bricks.length; i++) if (bricks[i].awake) awake++;
  for (let i = 0; i < world.contacts.length; i++) if (world.contacts[i].pen > maxPen) maxPen = world.contacts[i].pen;
  world.stats.contacts = world.contacts.length;
  world.stats.awake = awake;
  world.stats.maxPen = maxPen;
}

function integrate(world, seconds) {
  const n = Math.round(seconds / DT);
  for (let i = 0; i < n; i++) step(world, DT);
}

function snapshotPhysics(world) {
  const bricks = world.bricks;
  const out = new Float64Array(bricks.length * 4 + 8);
  let k = 0;
  out[k++] = world.car.x; out[k++] = world.car.y; out[k++] = world.car.z;
  out[k++] = world.car.vx; out[k++] = world.car.a;
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    out[k++] = b.x; out[k++] = b.y; out[k++] = b.z; out[k++] = b.a;
  }
  return out;
}

